INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("物理防御力（ダウン不可）アップ", "boss_def_lower_limit", 10091003, "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("魔法防御力（ダウン不可）アップ", "boss_magic_def_lower_limit", 10091004, "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("ＴＰダウンカット", "boss_tp_down_cut", 10091005, "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("ＴＰ上昇ダウン", 3, 10091006, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 4100910);
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("ＨＰ吸収ダウン", 9, 10091007, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", 4100910);
